mapper.select:
SELECT version
FROM content
WHERE code = #{contentCode}

SELECT status
FROM content
WHERE code = #{contentCode}

mapper.update:
UPDATE content
SET status = #{toStatus},
    version = version + 1,
    published_at = CASE
        WHEN #{toStatus} = 'published' THEN CURRENT_TIMESTAMP
        ELSE published_at
    END
WHERE code = #{contentCode}
  AND status = #{fromStatus}
  AND version = #{version}
